package dev.technix.client.feature.module.impl.misc;

import dev.technix.client.event.EventPriority;
import dev.technix.client.event.MicaEvents;
import dev.technix.client.event.events.input.KeyInputEvent;
import dev.technix.client.feature.module.Category;
import dev.technix.client.feature.module.Module;
import dev.technix.client.feature.module.impl.hud.notification.NotificationManager;
import dev.technix.client.feature.module.impl.hud.notification.NotificationType;
import dev.technix.client.feature.module.setting.BooleanSetting;
import dev.technix.client.feature.module.setting.ModeSetting;
import dev.technix.client.feature.module.setting.NumberSetting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;

/** Module that owns its own hold-key, because onKeyPress never fires while disabled. */
public final class Example extends Module {

    // All three of these round-trip through ProfileSnapshotCodec.
    private final BooleanSetting toast   = addSetting(new BooleanSetting("Toast", "Notify on fire", true));
    private final NumberSetting  reach   = addSetting(new NumberSetting("Reach", "Blocks", 3.0, 1.0, 6.0, 0.1));
    private final ModeSetting    mode    = addSetting(new ModeSetting("Mode", "How to run", "Normal", "Normal", "Fast"));

    private volatile boolean holdDown;

    public Example() {
        super("Example", "Hold V while enabled", Category.MISC);

        // House pattern (see Sprint / MovementFix): subscribe in the constructor and
        // self-gate. HIGHEST + receiveCancelled=true mirrors ModuleManager's own
        // KeyInputEvent listener, so we still see keys another module vetoed.
        MicaEvents.subscribe(KeyInputEvent.class, EventPriority.HIGHEST, true, e -> {
            if (e.key() != GLFW.GLFW_KEY_V) {
                return;
            }
            if (e.action() == GLFW.GLFW_PRESS) {
                this.holdDown = true;
            } else if (e.action() == GLFW.GLFW_RELEASE) {   // GLFW_REPEAT is ignored
                this.holdDown = false;
            }
        });
    }

    @Override
    public void onLoad() {
        // Runs before ConfigManager.autoLoad(): settings are still at defaults here.
        this.holdDown = false;
    }

    @Override
    public void onEnable() {
        // Also runs with default settings during profile load - do not cache values.
        this.holdDown = false;
    }

    /** ClientTickStartEvent, NORMAL, gated on isToggled(); runs after RotationHandler.onPreGameTick(). */
    @Override
    public void onPreUpdate() {
        LocalPlayer player = Minecraft.getInstance().player;
        if (player == null || !this.holdDown) {
            return;
        }
        if (this.toast.isEnabled()) {
            // Requires the "Notifications" HUD module to be enabled, or nothing renders
            // and nothing ages out of the queue.
            NotificationManager.getInstance().post(NotificationType.INFO, getName(),
                    this.mode.getValue() + " @ " + this.reach.getFloatValue());
        }
        // Local-only chat print. player.connection.sendChat(String) would talk to the server.
        player.sendSystemMessage(Component.literal("[" + getName() + "] fired"));
    }

    /** Only ever reached while toggled - never rely on this for a hold key. */
    @Override
    public boolean onKeyPress(int key, int action) {
        return true; // false here would also short-circuit ClickGUI.consumeKey
    }

    @Override
    public String getInfoUpdate() {
        return this.mode.getValue();
    }
}
